@Override public void afterCheckEachProject(@NonNull Context context) {
    Project project = context.getProject();
    List<String> jobServices = getJobServices(project);
    List<ServiceInfo> manifestServices = getManifestServices(project);
    Map<String, ServiceInfo> manifestByName = new HashMap<>();
    for (ServiceInfo info : manifestServices) manifestByName.put(info.name, info);
    for (String fqn : jobServices) {
        ServiceInfo info = manifestByName.get(fqn);
        if (info == null) {
            context.report(ISSUE, Location.create(context.file), "The JobService ... must be registered in the manifest with ...");
        } else if (!info.hasPermission) {
            context.report(ISSUE, info.location, "The manifest service ... must require ...");
        }
    }
    // Optionally: services with BIND_JOB_SERVICE permission but not extending JobService
    for (ServiceInfo info : manifestServices) {
        if (info.hasPermission && !jobServices.contains(info.name)) {
            context.report(ISSUE, info.location, "Only JobService subclasses should require ...");
        }
    }
}
```
