public class JobSchedulerDetector extends Detector implements Detector.UastScanner, Detector.XmlScanner {
    private static final String JOB_SERVICE = "android.app.job.JobService";
    private static final String BIND_JOB_SERVICE = "android.permission.BIND_JOB_SERVICE";

    public static final Issue ISSUE = Issue.create(
            "JobSchedulerService",
            "JobSchedulerService problems",
            "This check looks for ...",
            Category.CORRECTNESS,
            6,
            Severity.ERROR,
            new Implementation(JobSchedulerDetector.class,
                    EnumSet.of(Scope.JAVA_FILE, Scope.MANIFEST)));

    private final Map<Project, List<Pair<String, Location>>> mJobServices = Maps.newHashMap();
    private final Map<Project, List<Pair<String, Location>>> mManifestServices = Maps.newHashMap();

    @Override
    public void beforeCheckEachProject(@NonNull Context context) {
        Project project = context.getProject();
        mJobServices.put(project, new ArrayList<Pair<String, Location>>());
        mManifestServices.put(project, new ArrayList<Pair<String, Location>>());
    }

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(SdkConstants.TAG_SERVICE);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String name = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_NAME);
        if (name == null || name.isEmpty()) {
            return;
        }

        String permission = element.getAttributeNS(SdkConstants.ANDROID_URI, "permission");
        boolean hasPermission = BIND_JOB_SERVICE.equals(permission);
        Location location = context.getLocation(element);
        String fqn = resolveServiceName(name, context);
        getManifestServices(context.getProject()).add(Pair.of(fqn, location));
        if (hasPermission) {
            getServicesWithPermission(...).add(...)
        }
    }

    @Override
    public List<Class<? extends UElement>> getApplicableUastTypes() {
        return Collections.<Class<? extends UElement>>singletonList(UClass.class);
    }

    @Override
    public UElementHandler createUastHandler(@NonNull JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitClass(@NonNull UClass node) {
                if (context.getEvaluator().extendsClass(node, JOB_SERVICE, false)) {
                    String fqn = node.getQualifiedName();
                    if (fqn != null) {
                        getJobServices(context.getProject()).add(Pair.of(fqn, context.getLocation(node)));
                    }
                }
            }
        };
    }

    @Override
    public void afterCheckEachProject(@NonNull Context context) {
        Project project = context.getProject();
        List<Pair<String, Location>> jobServices = getJobServices(project);
        List<Pair<String, Location>> manifestServices = getManifestServices(project);

        Map<String, Location> servicesByName = new HashMap<>();
        Map<String, Boolean> permissionByName = new HashMap<>();
        for (Pair<String, Location> info : manifestServices) { ... }

        for (Pair<String, Location> jobService : jobServices) {
            Location location = servicesByName.get(...);
            if (location == null) { report not registered }
            else if (!permission) { report missing permission at location }
        }

        for ... if permission but not jobService -> report.
    }
}
