@Override
public void beforeCheckEachProject(@NonNull Context context) {
    Project project = context.getProject();
    mJobServices.put(project, new ArrayList<>());
    mManifestServices.put(project, new ArrayList<>());
}

@Override
public Collection<String> getApplicableElements() {
    return Collections.singletonList(SdkConstants.TAG_SERVICE);
}

@Override
public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
    String name = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_NAME);
    if (name == null || name.isEmpty()) {
        return;
    }
    String permission = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_PERMISSION);
    String fqn = resolveServiceName(name, context);
    Location location = context.getLocation(element);
    getManifestServices(context.getProject()).add(new ServiceInfo(fqn, BIND_JOB_SERVICE.equals(permission), location));
}

@Override
public List<Class<? extends PsiElement>> getApplicablePsiTypes() {
    return Collections.<Class<? extends PsiElement>>singletonList(PsiClass.class);
}

@Override
public JavaElementVisitor createPsiVisitor(@NonNull JavaContext context) {
    return new JavaElementVisitor() {
        @Override
        public void visitClass(PsiClass node) {
            JavaEvaluator evaluator = context.getEvaluator();
            if (evaluator.extendsClass(node, JOB_SERVICE, false)) {
                String fqn = node.getQualifiedName();
                if (fqn != null) {
                    getJobServices(context.getProject()).add(new ClassInfo(fqn, context.getLocation(node)));
                }
            }
        }
    };
}
```

